import React from 'react';
import styled from 'styled-components';
import { pizzaRed } from '../Styles/colors';
import { Title } from '../Styles/title';
import  cart from './shopping_cart.svg'

const NavbarStyled = styled.div`
    background-color: ${pizzaRed};
    padding: 20px;
    position: fixed;
    width: 100%;
    z-index: 999;
`

const Logo = styled(Title)`
  font-size: 20px;
  color: white;
  font-family: 'Great Vibes', cursive;
  text-shadow: 1px 1px 1px black;
`


export function Navbar({ isVisible, onStateChange }) {
  
   const handleChange = (event) => {
    onStateChange(event.target.value);
    isVisible === false ? isVisible = true : isVisible = false
    console.log(isVisible);
  };

  return (
    <NavbarStyled>
      <Logo>
        Demissies' Pizzeria 
        <span role="img" aria-label="pizza slice">🍕</span>
        <div class="cart">
          <button value={isVisible} onClick={handleChange} >
          <img src={cart} alt="shopping-cart-icon" />
          <div>Cart</div>
          </button>
        </div>
      </Logo>
    </NavbarStyled>
  )
}