import React, { useState } from 'react'; //useState for react hooks
import { Navbar } from './Navbar/Navbar.js';
import { Banner } from './Banner/Banner';
import { Menu } from './Menu/Menu';
import { FoodDialog } from './FoodDialogue/FoodDialogue';
import { GlobalStyle } from './Styles/GlobalStyles';
import { Order } from './Order/Order';
import { useTitle } from './Hooks/useTitle';

import { useOpenFood } from './Hooks/useOpenFood';
import { useOrders } from './Hooks/useOrders';

function App () {
  const [isVisible, setIsVisible] = useState(false);
  const handleStateChange = (newState) => {
    setIsVisible(!isVisible);
    console.log(isVisible)
  };
  const openFood = useOpenFood();
  const orders = useOrders();
  useTitle({ ...openFood, ...orders})
    return (
      <>
      <GlobalStyle />
      <FoodDialog class='test' {...openFood} {...orders} />
        <Navbar isVisible={isVisible} onStateChange={handleStateChange} />
        {isVisible === true ? <Order isVisible={isVisible} {...orders} {...openFood} /> : null}
        <Banner />
        {isVisible === false ? <Menu style={{ marginRight: '400px'}} {...openFood} /> :  <Menu style={{ marginRight: '0px'}} isVisible={isVisible} {...openFood} /> }
      </>
    );
  }

export default App;